package io.knowledgebrain.notification;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import tools.jackson.databind.json.JsonMapper;
final class GroupReviewSnapshot {
 record Page(List<ReviewSignal.Signal> items,UUID nextAfter) {}
 private final URI origin;private final HttpClient client;private final String key;private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 GroupReviewSnapshot(String origin,String trust,String key)throws Exception{this.origin=NotificationHttp.origin(origin);client=NotificationHttp.client(trust);if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Dedicated export credential required");this.key=key;}
 void backfill(GroupReviewStore store){UUID after=null;do{var r=NotificationHttp.send(client,HttpRequest.newBuilder(origin.resolve("/internal/collaboration/review-signals?limit=50"+(after==null?"":"&after="+after))).header("Authorization","Bearer "+key).timeout(Duration.ofSeconds(8)).GET().build(),131072);if(r.statusCode()!=200)throw new IllegalStateException("Canonical review recovery unavailable");var p=json.readValue(r.body(),Page.class);if(p==null||p.items()==null||p.items().size()>50)throw ReviewSignal.bad();UUID last=after;for(var item:p.items()){ReviewSignal.validate(item);if(last!=null&&item.eventId().toString().compareTo(last.toString())<=0)throw ReviewSignal.bad();store.accept(item);last=item.eventId();}if(p.nextAfter()!=null&&(p.items().size()!=50||!p.nextAfter().equals(last)))throw ReviewSignal.bad();after=p.nextAfter();}while(after!=null);store.seededNow();}
}
